export const CURATED_OPEN_VIDEOS: readonly CuratedOpenVideo[] = [
  ...CURATED_PART_1,
  ...CURATED_PART_2,
  ...CURATED_PART_3,
  ...CURATED_PART_4,
  ...CURATED_PART_5,
  ...CURATED_PART_6,
  ...CURATED_PART_7,
  ...CURATED_PART_8,
  ...CURATED_PART_9,
  ...CURATED_PART_10,
  ...CURATED_PART_11,
];

export function toCuratedCmsItem(item: CuratedOpenVideo, includePlayUrl = false, compact = false) {
  const vodId = encodeCuratedVideoVodId(item);
  const durationLabel = formatMediaDuration(item.durationSeconds);
  const hasEpisodes = Boolean(item.episodes && item.episodes.length > 0);
  const isDirect = Boolean(item.directPlayUrl || hasEpisodes);
  const remarksLabel = hasEpisodes && item.episodes!.length > 1
    ? `全${item.episodes!.length}集连播 · ${durationLabel} · ${item.licenceLabel}`
    : `${durationLabel} · ${item.licenceLabel}`;
  const playFromPayload = hasEpisodes
    ? item.sourceLabel
    : item.directPlayUrl
      ? item.backupDirectPlayUrl
        ? `${item.sourceLabel}$$$${item.backupSourceLabel || '超清备用直连'}`
        : item.sourceLabel
      : undefined;
  const playUrlPayload = hasEpisodes
    ? item.episodes!
        .map((ep) => `${ep.title.replace(/[#$]/g, ' ').trim()}$${ep.url}`)
        .join('#')
    : item.directPlayUrl
      ? item.backupDirectPlayUrl
        ? `超清直连$${item.directPlayUrl}$$$备用直连$${item.backupDirectPlayUrl}`
        : `超清直连$${item.directPlayUrl}`
      : undefined;

  return {
    vod_id: vodId,
    vod_name: compact ? item.zhTitle : `${item.zhTitle} / ${item.enTitle}`,
    vod_pic: item.poster,
    type_name: compact ? item.sourceLabel : `${item.sourceLabel} · ${item.licenceLabel}`,
    vod_year: item.year,
    vod_remarks: remarksLabel,
    vod_direct: isDirect,
    ...(compact && !includePlayUrl
      ? {}
      : {
          vod_content: [
            `中文导览：${item.summary}`,
            `英文原名：${item.enTitle} (${item.year})`,
            hasEpisodes && item.episodes!.length > 1 ? `剧集规格：共 ${item.episodes!.length} 集连续播放` : `片长：${durationLabel}`,
            `授权说明：${item.licenceLabel}`,
          ].join('\n'),
        }),
    ...(includePlayUrl && playUrlPayload && playFromPayload
      ? {
          vod_play_from: playFromPayload,
          vod_play_url: playUrlPayload,
        }
      : {}),
  };
}

function normalizeMatchText(value: string): string {
  return value.trim().toLowerCase().replace(/[\s\p{P}\p{S}]+/gu, '');
}

/** 在内置精选目录中执行中英文片名、别名与题材词双向检索（按主标题精确/前缀/包含 > 别名 > 题材排序） */
export function searchCuratedOpenVideos(query: string, allowShort = true): CuratedOpenVideo[] {
  const norm = normalizeMatchText(query);
  if (!norm) return [];
  const scored: { item: CuratedOpenVideo; score: number }[] = [];

  for (const item of CURATED_OPEN_VIDEOS) {
    if (!allowShort && item.durationSeconds < 20 * 60) continue;
    const zhNorm = normalizeMatchText(item.zhTitle);
    const enNorm = normalizeMatchText(item.enTitle);

    let score = 0;
    const exactAlias = item.aliases.some((alias) => normalizeMatchText(alias) === norm);
    if (zhNorm === norm || enNorm === norm || exactAlias) {
      score = 5;
    } else if (zhNorm.startsWith(norm) || enNorm.startsWith(norm)) {
      score = 4;
    } else if (
      zhNorm.includes(norm) ||
      enNorm.includes(norm) ||
      (norm.length >= 2 &&
        ((zhNorm.length >= 2 && !/^\d+$/.test(zhNorm) && norm.includes(zhNorm)) ||
          (enNorm.length >= 2 && !/^\d+$/.test(enNorm) && norm.includes(enNorm))))
    ) {
      score = 3;
    } else if (
      item.aliases.some((alias) => {
        const na = normalizeMatchText(alias);
        return na.includes(norm) || (norm.length >= 2 && na.length >= 2 && norm.includes(na));
      })
    ) {
      score = 2;
    } else if (
      ((norm === '动画' || norm === '动漫' || norm === '开源动画') && item.category === 'animation') ||
      ((norm === '喜剧' || norm === '动作') && item.category === 'comedy') ||
      ((norm === '科幻' || norm === '悬疑' || norm === '惊悚' || norm === '恐怖') && item.category === 'thriller') ||
      ((norm === '太空' || norm === '纪录片' || norm === '宇宙' || norm === 'nasa') && item.category === 'space') ||
      ((norm === '华语' || norm === '国产' || norm === '老电影') && item.category === 'chinese')
    ) {
      score = 1;
    }

    if (score > 0) {
      scored.push({ item, score });
    }
  }

  return scored.sort((a, b) => b.score - a.score).map((x) => x.item);
}

export function findCuratedOpenVideoBySlug(slug: string): CuratedOpenVideo | undefined {
  return CURATED_OPEN_VIDEOS.find((item) => item.slug === slug);
}

export function browseCuratedOpenVideos(category: OpenBrowseCategory = 'all'): CuratedOpenVideo[] {
  const pool = category === 'all' ? [...CURATED_OPEN_VIDEOS] : CURATED_OPEN_VIDEOS.filter((item) => item.category === category);
  // 优先将国内直连单集大片与多集连播剧集排在各分类前排，兼顾首屏零等待体验与完整公版馆藏
  const direct = pool.filter((item) => Boolean(item.directPlayUrl || (item.episodes && item.episodes.length > 0)));
  const cloud = pool.filter((item) => !item.directPlayUrl && !(item.episodes && item.episodes.length > 0));
  return [...direct, ...cloud];
}

/**
 * 为首页 `/api/search` 相关性过滤器展开内置精选片库的别名与中文题材词：
 * 确保用户在首页搜「大白兔」「三体星系行星」「莫里亚蒂教授」或「科幻」「喜剧」「太空」时不被误杀。
 */
export function expandCuratedQueryAliases(query: string): string[] {
  const norm = normalizeMatchText(query);
  if (!norm) return [];
  const out = new Set<string>();
  for (const item of CURATED_OPEN_VIDEOS) {
    const forms = [item.zhTitle, item.enTitle, ...item.aliases];
    if (forms.some((f) => {
      const nf = normalizeMatchText(f);
      return nf === norm || (norm.length >= 2 && nf.length >= 2 && (nf.includes(norm) || norm.includes(nf)));
    })) {
      out.add(item.zhTitle);
      out.add(item.enTitle);
    }
    if (
      ((norm === '动画' || norm === '动漫' || norm === '开源动画') && item.category === 'animation') ||
      ((norm === '喜剧' || norm === '动作') && item.category === 'comedy') ||
      ((norm === '科幻' || norm === '悬疑' || norm === '惊悚' || norm === '恐怖') && item.category === 'thriller') ||
      ((norm === '太空' || norm === '纪录片' || norm === '宇宙' || norm === 'nasa') && item.category === 'space') ||
      ((norm === '华语' || norm === '国产' || norm === '老电影') && item.category === 'chinese')
    ) {
      out.add(item.zhTitle);
    }
  }
  return [...out];
}
